1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="My Page">
7	  <meta name="robots" content="index, follow">
8	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
9	  <meta name="theme-color" content="#111214" media="(prefers-color-scheme: dark)">
10	  <meta property="og:title" content="My Page">
11	  <meta property="og:description" content="My Page">
12	  <meta property="og:type" content="website">
13	  <meta property="og:url" content="https://example.com/">
14	  <meta name="twitter:card" content="summary">
15	  <meta name="twitter:title" content="My Page">
16	  <meta name="twitter:description" content="My Page">
17	  <link rel="canonical" href="https://example.com/">
18	  <link rel="icon" href="data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2016%2016'%3E%3Ccircle%20cx='8'%20cy='8'%20r='7'%20fill='%232563eb'/%3E%3C/svg%3E">
19	  <title>My Page</title>
20	  <script type="application/ld+json">
21	  {
22	    "@context": "https://schema.org",
23	    "@type": "WebSite",
24	    "name": "My Page",
25	    "url": "https://example.com/"
26	  }
27	  </script>
28	  <style>
29	    :root {
30	      color-scheme: light dark;
31	      --bg: #ffffff;
32	      --fg: #1a1a1a;
33	      --muted: #555;
34	      --accent: #2563eb;
35	      --border: #e5e7eb;
36	    }
37	
38	    @media (prefers-color-scheme: dark) {
39	      :root {
40	        --bg: #111214;
41	        --fg: #e8e8e8;
42	        --muted: #aaa;
43	        --accent: #60a5fa;
44	        --border: #2a2b2e;
45	      }
46	    }
47	
48	    * {
49	      box-sizing: border-box;
50	    }
51	
52	    html {
53	      scroll-behavior: smooth;
54	    }
55	
56	    @media (prefers-reduced-motion: reduce) {
57	      html {
58	        scroll-behavior: auto;
59	      }
60	    }
61	
62	    ::selection {
63	      background: var(--accent);
64	      color: var(--bg);
65	    }
66	
67	    body {
68	      font-family: system-ui, -apple-system, sans-serif;
69	      max-width: 40rem;
70	      margin: 3rem auto;
71	      padding: 0 1rem;
72	      line-height: 1.6;
73	      color: var(--fg);
74	      background: var(--bg);
75	    }
76	
77	    @media (max-width: 30rem) {
78	      body {
79	        margin: 1.5rem auto;
80	      }
81	    }
82	
83	    h1 {
84	      font-size: clamp(1.75rem, 5vw, 2.5rem);
85	      margin-bottom: 0.5rem;
86	    }
87	
88	    p {
89	      color: var(--muted);
90	      max-width: 34rem;
91	    }
92	
93	    a {
94	      color: var(--accent);
95	      transition: opacity 0.15s ease;
96	    }
97	
98	    a:hover {
99	      opacity: 0.8;
100	    }
101	
102	    a:focus-visible,
103	    button:focus-visible {
104	      outline: 2px solid var(--accent);
105	      outline-offset: 2px;
106	    }
107	
108	    .skip-link {
109	      position: absolute;
110	      left: -9999px;
111	      top: 0;
112	      background: var(--accent);
113	      color: var(--bg);
114	      padding: 0.5rem 1rem;
115	      border-radius: 0.25rem;
116	      z-index: 10;
117	    }
118	
119	    .skip-link:focus {
120	      left: 1rem;
121	      top: 1rem;
122	    }
123	
124	    main:focus {
125	      outline: none;
126	    }
127	
128	    nav ul {
129	      display: flex;
130	      flex-wrap: wrap;
131	      gap: 1rem;
132	      list-style: none;
133	      padding: 0;
134	      margin: 0 0 2rem;
135	    }
136	
137	    nav a {
138	      text-decoration: none;
139	      font-weight: 500;
140	      opacity: 1;
141	    }
142	
143	    nav a:hover {
144	      text-decoration: underline;
145	    }
146	
147	    nav a[aria-current="page"] {
148	      text-decoration: underline;
149	      color: var(--fg);
150	      font-weight: 700;
151	    }
152	
153	    h2 {
154	      margin-top: 2rem;
155	      margin-bottom: 0.5rem;
156	    }
157	
158	    section + section {
159	      margin-top: 1.5rem;
160	    }
161	
162	    section {
163	      scroll-margin-top: 1.5rem;
164	    }
165	
166	    footer {
167	      margin-top: 3rem;
168	      padding-top: 1.5rem;
169	      border-top: 1px solid var(--border);
170	      font-size: 0.875rem;
171	      color: var(--muted);
172	    }
173	
174	    @media print {
175	      .skip-link,
176	      nav {
177	        display: none;
178	      }
179	    }
180	  </style>
181	</head>
182	<body>
183	  <a class="skip-link" href="#main">Skip to content</a>
184	  <nav aria-label="Primary">
185	    <ul>
186	      <li><a href="#home" data-nav-link aria-current="page">Home</a></li>
187	      <li><a href="#about" data-nav-link>About</a></li>
188	      <li><a href="#contact" data-nav-link>Contact</a></li>
189	    </ul>
190	  </nav>
191	  <main id="main" tabindex="-1">
192	    <section id="home" aria-labelledby="home-heading">
193	      <h1 id="home-heading">My Page</h1>
194	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
195	    </section>
196	
197	    <section id="about" aria-labelledby="about-heading">
198	      <h2 id="about-heading">About</h2>
199	      <p>Add a short description of what this page or project is about here.</p>
200	    </section>
201	
202	    <section id="contact" aria-labelledby="contact-heading">
203	      <h2 id="contact-heading">Contact</h2>
204	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
205	    </section>
206	  </main>
207	  <footer>
208	    <p>&copy; <span id="year">2026</span> My Page. All rights reserved.</p>
209	  </footer>
210	  <script>
211	    const yearEl = document.getElementById('year');
212	    if (yearEl) yearEl.textContent = String(new Date().getFullYear());
213	
214	    const navLinks = document.querySelectorAll('[data-nav-link]');
215	    const sections = [...navLinks]
216	      .map(link => document.querySelector(link.getAttribute('href')))
217	      .filter(Boolean);
218	
219	    const setActive = (id) => {
220	      navLinks.forEach(link => {
221	        if (link.getAttribute('href') === `#${id}`) {
222	          link.setAttribute('aria-current', 'page');
223	        } else {
224	          link.removeAttribute('aria-current');
225	        }
226	      });
227	    };
228	
229	    setActive(sections[0]?.id);
230	
231	    navLinks.forEach(link => {
232	      link.addEventListener('click', () => setActive(link.getAttribute('href').slice(1)));
233	    });
234	
235	    if ('IntersectionObserver' in window) {
236	      const observer = new IntersectionObserver((entries) => {
237	        const visible = entries
238	          .filter(entry => entry.isIntersecting)
239	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
240	        if (visible) setActive(visible.target.id);
241	      }, { rootMargin: '-40% 0px -50% 0px' });
242	      sections.forEach(section => section && observer.observe(section));
243	    }
244	  </script>
245	</body>
246	</html>
